import { InfoForQuestCachingService } from "../caching/services/info-for-quest-caching.service";
import { Injectable } from "@nestjs/common";

/**
 * Service: ConnectQuestService
 *
 * Dieser Service verwaltet die Logik zum temporären Caching der Informationen, die benötigt werden
 * um eine Quest zu verbinden. Dies wird über einen einmaligen PIN (One-Time PIN),
 * der im Cache (Redis) gespeichert wird ermöglicht.
 *
 * Hauptfunktionalitäten:
 * - Erzeugen eines zufälligen 4-stelligen PINs
 * - Packen und Speichern von Token-, Progress- und User-ID-Daten
 * - Caching dieser Informationen unter einem generierten PIN
 * - Auslesen des aktuellsten PINs sowie der zugehörigen Daten
 *
 */
@Injectable()
export class ConnectQuestService {
	constructor(
		private readonly infoCache: InfoForQuestCachingService,
	) {
	}

	/**
	 * Generiert eine zufällige 4-stellige PIN als String.
	 * Beispiel: "1234"
	 */
	private genPin(): string {
		return Math.floor(1000 + Math.random() * 9000).toString();
	}

	/**
	 * Holt ProgressID, JWT-Token und UserID aus dem Cache
	 * und packt sie als CSV-String zusammen.
	 *
	 * Beispiel-Rückgabe: "jwtTokenValue,progressId,42"
	 */
	private async packProgressIdTokenUserId(){
		const id: string = await this.infoCache.getProgressID();
		const token: string = await this.infoCache.getToken();
		const userId: string = await this.infoCache.getCurrentUserId();
		const pack: string[] = [token, id, userId];
		return pack.toString();
	}

	/**
	 * Speichert eine ProgressID und eine UserID im Cache.
	 *
	 * @param progId - Kursfortschritt-ID
	 * @param userId - Benutzer-ID
	 */
	async cacheProgressIdUserId(progId: string, userId: number){
		await this.infoCache.setProgressID(progId);
		await this.infoCache.setCurrentUserId(userId.toString());
	}

	/**
	 * Extrahiert das Token aus einem übergebenen JSON-String
	 * und speichert es im Cache.
	 *
	 * @param query - JSON-String wie: '{"token": "abc123"}'
	 */
	async cacheToken(query: string){
		const parsed = JSON.parse(query);
		const token = parsed.token;
		await this.infoCache.setToken(token);
	}

	/**
	 * Generiert eine neue PIN und speichert diese zusammen mit
	 * ProgressID, JWT und UserID im Cache.
	 *
	 * Format im Cache: Key = "pin:1234", Value = "jwt,progressId,userId"
	 */
	async cachePinTokenProgIdUserId() {
		let pin: string = this.genPin();
		const packed: string = await this.packProgressIdTokenUserId();
		await this.infoCache.setPin(pin, packed);
	}

	/**
	 * Erstellt und speichert eine neue PIN in Redis, liest anschließend alle verfügbaren PINs
	 * aus dem Cache und gibt die neueste zurück.
	 *
	 * @returns Der neueste PIN als Zeichenkette.
	 */
	async getPin(): Promise<string> {
		await this.cachePinTokenProgIdUserId();
		return await this.infoCache.scanForPin();
	}

	/**
	 * Holt den Cache-Wert für eine gegebene PIN und gibt diesen zurück.
	 * Erwarteter Rückgabewert ist ein String im CSV-Format: "jwt,progressId,userId"
	 *
	 * @param pin - Die zu suchende PIN als Zahl
	 * @returns Der zugehörige Cachewert oder `undefined`, falls nicht vorhanden
	 */
	async getPerPin(pin: number): Promise<string> {
		return await this.infoCache.getTokenID(pin);
	}
}